SELECT l.InvoiceLineID,l.InvoiceID,i.IsCreditNote,l.Quantity,l.UnitPrice,l.TaxRate,l.TaxAmount,l.ExtendedPrice,l.LineProfit,l.ExtendedPrice-(l.Quantity*l.UnitPrice+l.TaxAmount) Difference FROM raw.Sales_InvoiceLines l JOIN raw.Sales_Invoices i USING(InvoiceID) WHERE l.ExtendedPrice<>(l.Quantity*l.UnitPrice+l.TaxAmount) OR l.TaxAmount<>ROUND(l.Quantity*l.UnitPrice*l.TaxRate*CAST(0.01 AS DECIMAL(3,2)),2) ORDER BY l.InvoiceLineID